# -*- coding: utf-8 -*-
# Rafraichissement visuel : typographie plus chaleureuse (Baloo 2), couleurs plus vives,
# coins arrondis adoucis, degrade de marque, 'manque' en gris-ambre neutre (pas rouge),
# accueil personnalise, messages plus chaleureux
# A lancer depuis la racine du dossier pompiers-app : python3 apply_update_12.py
import pathlib

FILES = {}

FILES['frontend/tailwind.config.js'] = '/** @type {import(\'tailwindcss\').Config} */\nexport default {\n  content: ["./index.html", "./src/**/*.{js,ts,jsx,tsx}"],\n  theme: {\n    extend: {\n      colors: {\n        bg: "#F2FAFB",\n        surface: "#FFFFFF",\n        surface2: "#EAF3F6",\n        border: "#D5E6EA",\n        accent: "#0EA0B0",\n        accentSoft: "#3FBFC9",\n        success: "#4CAF50",\n        warn: "#C9A227",\n        text: "#152B31",\n        muted: "#5C7A81",\n      },\n      fontFamily: {\n        display: ["Baloo 2", "sans-serif"],\n        body: ["Inter", "sans-serif"],\n        mono: ["IBM Plex Mono", "monospace"],\n      },\n      borderRadius: {\n        md: "0.6rem",\n        lg: "0.9rem",\n        xl: "1.25rem",\n        "2xl": "1.6rem",\n      },\n    },\n  },\n  plugins: [],\n};\n'
FILES['frontend/index.html'] = '<!doctype html>\n<html lang="fr">\n  <head>\n    <meta charset="UTF-8" />\n    <meta name="viewport" content="width=device-width, initial-scale=1.0" />\n    <meta name="theme-color" content="#0EA0B0" />\n    <title>GoTeam</title>\n    <link rel="icon" type="image/png" sizes="32x32" href="/favicon-32.png" />\n    <link rel="icon" type="image/png" sizes="64x64" href="/favicon-64.png" />\n    <link rel="apple-touch-icon" href="/icon-192.png" />\n    <link rel="preconnect" href="https://fonts.googleapis.com" />\n    <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />\n    <link\n      href="https://fonts.googleapis.com/css2?family=Baloo+2:wght@500;600;700;800&family=Inter:wght@400;500;600;700&family=IBM+Plex+Mono:wght@500;600&display=swap"\n      rel="stylesheet"\n    />\n    <link rel="manifest" href="/manifest.json" />\n  </head>\n  <body>\n    <div id="root"></div>\n    <script type="module" src="/src/main.tsx"></script>\n  </body>\n</html>\n'
FILES['frontend/src/index.css'] = '@tailwind base;\n@tailwind components;\n@tailwind utilities;\n\n:root {\n  color-scheme: light;\n}\n\nhtml,\nbody,\n#root {\n  height: 100%;\n}\n\nbody {\n  background-color: #f2fafb;\n  background-image:\n    radial-gradient(circle at 8% -5%, rgba(14, 160, 176, 0.10), transparent 42%),\n    radial-gradient(circle at 95% 105%, rgba(76, 175, 80, 0.08), transparent 48%);\n  color: #152b31;\n  font-family: "Inter", sans-serif;\n}\n\nh1,\nh2,\nh3,\n.font-display {\n  font-family: "Baloo 2", sans-serif;\n  letter-spacing: 0.01em;\n  font-weight: 700;\n}\n\n/* Degrade signature de la marque (bleu vers vert, repris du logo), pour les elements\n   les plus visibles (logo, ecrans de connexion, gros boutons d\'action). */\n.brand-gradient {\n  background-image: linear-gradient(120deg, #0EA0B0 0%, #4CAF50 100%);\n}\n.brand-gradient-text {\n  background-image: linear-gradient(120deg, #0EA0B0 0%, #4CAF50 100%);\n  -webkit-background-clip: text;\n  background-clip: text;\n  color: transparent;\n}\n\n/* Focus visible clair pour l\'accessibilite clavier */\na:focus-visible,\nbutton:focus-visible,\ninput:focus-visible,\nselect:focus-visible,\ntextarea:focus-visible {\n  outline: 2px solid #0ea0b0;\n  outline-offset: 2px;\n}\n\n@media (prefers-reduced-motion: reduce) {\n  * {\n    animation-duration: 0.001ms !important;\n    transition-duration: 0.001ms !important;\n  }\n}\n\n/* --- Tampon de validation (signature visuelle de l\'app) --- */\n.stamp-cell {\n  position: relative;\n  border-radius: 5px;\n  transition: transform 120ms ease, background-color 150ms ease;\n}\n.stamp-cell.done {\n  background-color: rgba(76, 175, 80, 0.18);\n  border: 1px solid rgba(76, 175, 80, 0.55);\n}\n/* "manque" reste neutre (gris-ambre) plutot que rouge : on encourage, on ne sanctionne pas */\n.stamp-cell.missed {\n  background-color: rgba(201, 162, 39, 0.12);\n  border: 1px solid rgba(201, 162, 39, 0.35);\n}\n.stamp-cell.future {\n  background-color: transparent;\n  border: 1px dashed #d5e6ea;\n}\n\n.stamp-btn {\n  transition: transform 100ms ease, box-shadow 150ms ease;\n}\n.stamp-btn:active {\n  transform: scale(0.94) rotate(-2deg);\n}\n\n/* Petit rebond satisfaisant quand une seance vient d\'etre validee */\n@keyframes pop-success {\n  0% { transform: scale(0.8); opacity: 0.5; }\n  60% { transform: scale(1.12); }\n  100% { transform: scale(1); opacity: 1; }\n}\n.pop-success {\n  animation: pop-success 320ms ease-out;\n}\n'
FILES['frontend/src/pages/Login.tsx'] = 'import { FormEvent, useState } from "react";\nimport { Link, Navigate, useNavigate } from "react-router-dom";\nimport { useAuth } from "../context/AuthContext";\nimport { ApiError } from "../api/client";\n\nexport default function Login() {\n  const { login, user } = useAuth();\n  const navigate = useNavigate();\n  const [email, setEmail] = useState("");\n  const [password, setPassword] = useState("");\n  const [error, setError] = useState<string | null>(null);\n  const [busy, setBusy] = useState(false);\n\n  if (user) return <Navigate to="/aujourdhui" replace />;\n\n  async function onSubmit(e: FormEvent) {\n    e.preventDefault();\n    setError(null);\n    setBusy(true);\n    try {\n      await login(email, password);\n      navigate("/aujourdhui");\n    } catch (err) {\n      setError(err instanceof ApiError ? err.message : "Connexion impossible, réessaie.");\n    } finally {\n      setBusy(false);\n    }\n  }\n\n  return (\n    <div className="min-h-screen flex items-center justify-center px-5">\n      <div className="w-full max-w-sm">\n        <div className="flex justify-center mb-8">\n          <img src="/logo-full.png" alt="GoTeam" className="h-24 w-auto" />\n        </div>\n\n        <div className="bg-surface border border-border rounded-xl p-6">\n          <h1 className="font-display text-2xl uppercase tracking-wide mb-1">Content de te revoir !</h1>\n          <p className="text-muted text-sm mb-6">On reprend la ou tu t\'es arrete(e) ?</p>\n\n          <form onSubmit={onSubmit} className="space-y-4">\n            <div>\n              <label className="block text-sm text-muted mb-1" htmlFor="email">\n                Email\n              </label>\n              <input\n                id="email"\n                type="email"\n                required\n                value={email}\n                onChange={(e) => setEmail(e.target.value)}\n                className="w-full bg-surface2 border border-border rounded-md px-3 py-2 text-text"\n              />\n            </div>\n            <div>\n              <div className="flex items-center justify-between mb-1">\n                <label className="block text-sm text-muted" htmlFor="password">\n                  Mot de passe\n                </label>\n                <Link to="/mot-de-passe-oublie" className="text-xs text-accent hover:text-accentSoft">\n                  Oublié ?\n                </Link>\n              </div>\n              <input\n                id="password"\n                type="password"\n                required\n                value={password}\n                onChange={(e) => setPassword(e.target.value)}\n                className="w-full bg-surface2 border border-border rounded-md px-3 py-2 text-text"\n              />\n            </div>\n\n            {error && <p className="text-sm text-accent">{error}</p>}\n\n            <button\n              type="submit"\n              disabled={busy}\n              className="w-full brand-gradient hover:opacity-90 transition-opacity text-white font-semibold rounded-md py-2.5 disabled:opacity-60"\n            >\n              {busy ? "Connexion..." : "Se connecter"}\n            </button>\n          </form>\n        </div>\n\n        <p className="text-center text-sm text-muted mt-4">\n          Pas encore de compte ?{" "}\n          <Link to="/inscription" className="text-accent hover:text-accentSoft">\n            Crée-en un\n          </Link>\n        </p>\n      </div>\n    </div>\n  );\n}\n'
FILES['frontend/src/pages/Register.tsx'] = 'import { FormEvent, useState } from "react";\nimport { Link, Navigate, useNavigate } from "react-router-dom";\nimport { useAuth } from "../context/AuthContext";\nimport { ApiError } from "../api/client";\nimport { SPORTS_LIST, SPORT_LEVELS } from "../lib/sports";\n\nexport default function Register() {\n  const { register, user } = useAuth();\n  const navigate = useNavigate();\n  const [name, setName] = useState("");\n  const [email, setEmail] = useState("");\n  const [password, setPassword] = useState("");\n  const [sport, setSport] = useState("");\n  const [sportLevel, setSportLevel] = useState<"LOISIR" | "COMPETITION" | "">("");\n  const [error, setError] = useState<string | null>(null);\n  const [busy, setBusy] = useState(false);\n\n  if (user) return <Navigate to="/aujourdhui" replace />;\n\n  async function onSubmit(e: FormEvent) {\n    e.preventDefault();\n    setError(null);\n    setBusy(true);\n    try {\n      await register(email, password, name, sport || null, sportLevel || null);\n      navigate("/profil");\n    } catch (err) {\n      setError(err instanceof ApiError ? err.message : "Inscription impossible, réessaie.");\n    } finally {\n      setBusy(false);\n    }\n  }\n\n  return (\n    <div className="min-h-screen flex items-center justify-center px-5">\n      <div className="w-full max-w-sm">\n        <div className="flex justify-center mb-8">\n          <img src="/logo-full.png" alt="GoTeam" className="h-24 w-auto" />\n        </div>\n\n        <div className="bg-surface border border-border rounded-xl p-6">\n          <h1 className="font-display text-2xl uppercase tracking-wide mb-1">Bienvenue !</h1>\n          <p className="text-muted text-sm mb-6">Que tu sois sportif aguerri ou juste envie de bouger un peu plus, tu es au bon endroit.</p>\n\n          <form onSubmit={onSubmit} className="space-y-4">\n            <div>\n              <label className="block text-sm text-muted mb-1" htmlFor="name">\n                Prenom\n              </label>\n              <input\n                id="name"\n                required\n                value={name}\n                onChange={(e) => setName(e.target.value)}\n                className="w-full bg-surface2 border border-border rounded-md px-3 py-2 text-text"\n              />\n            </div>\n            <div>\n              <label className="block text-sm text-muted mb-1" htmlFor="email">\n                Email\n              </label>\n              <input\n                id="email"\n                type="email"\n                required\n                value={email}\n                onChange={(e) => setEmail(e.target.value)}\n                className="w-full bg-surface2 border border-border rounded-md px-3 py-2 text-text"\n              />\n            </div>\n            <div>\n              <label className="block text-sm text-muted mb-1" htmlFor="password">\n                Mot de passe\n              </label>\n              <input\n                id="password"\n                type="password"\n                required\n                minLength={8}\n                value={password}\n                onChange={(e) => setPassword(e.target.value)}\n                className="w-full bg-surface2 border border-border rounded-md px-3 py-2 text-text"\n              />\n              <p className="text-xs text-muted mt-1">8 caractères minimum.</p>\n            </div>\n\n            <div>\n              <label className="block text-sm text-muted mb-1" htmlFor="sport">\n                Ton sport / activité principale (optionnel)\n              </label>\n              <select\n                id="sport"\n                value={sport}\n                onChange={(e) => setSport(e.target.value)}\n                className="w-full bg-surface2 border border-border rounded-md px-3 py-2 text-text"\n              >\n                <option value="">Je ne pratique rien en particulier / je découvre</option>\n                {SPORTS_LIST.map((s) => (\n                  <option key={s} value={s}>\n                    {s}\n                  </option>\n                ))}\n              </select>\n            </div>\n\n            {sport && (\n              <div>\n                <label className="block text-sm text-muted mb-1">Niveau de pratique</label>\n                <div className="flex gap-2">\n                  {SPORT_LEVELS.map((lvl) => (\n                    <button\n                      type="button"\n                      key={lvl.value}\n                      onClick={() => setSportLevel(lvl.value)}\n                      className={`flex-1 text-xs px-3 py-2 rounded-md border ${\n                        sportLevel === lvl.value\n                          ? "bg-accent/20 border-accent text-text"\n                          : "bg-surface2 border-border text-muted"\n                      }`}\n                    >\n                      {lvl.label}\n                    </button>\n                  ))}\n                </div>\n              </div>\n            )}\n\n            {error && <p className="text-sm text-accent">{error}</p>}\n\n            <button\n              type="submit"\n              disabled={busy}\n              className="w-full brand-gradient hover:opacity-90 transition-opacity text-white font-semibold rounded-md py-2.5 disabled:opacity-60"\n            >\n              {busy ? "Création..." : "Créer mon compte"}\n            </button>\n          </form>\n        </div>\n\n        <p className="text-center text-sm text-muted mt-4">\n          Déjà un compte ?{" "}\n          <Link to="/connexion" className="text-accent hover:text-accentSoft">\n            Connecté-toi\n          </Link>\n        </p>\n      </div>\n    </div>\n  );\n}\n'
FILES['frontend/src/pages/Today.tsx'] = 'import { useEffect, useMemo, useState } from "react";\nimport { Link } from "react-router-dom";\nimport { api } from "../api/client";\nimport { useAuth } from "../context/AuthContext";\nimport DurationInput from "../components/DurationInput";\nimport CircuitRunner from "../components/CircuitRunner";\nimport ExerciseMediaModal from "../components/ExerciseMediaModal";\nimport { secondsToMMSS } from "../lib/duration";\n\ninterface TodayExerciseItem {\n  kind: "exercise";\n  campExerciseId: string;\n  campId: string;\n  campName: string;\n  exerciseId: string;\n  exerciseName: string;\n  description: string | null;\n  unit: "REPS" | "SECONDS";\n  imageBase64: string | null;\n  videoUrl: string | null;\n  targetSets: number;\n  targetMode: "FIXED" | "MAX";\n  targetValue: number | null;\n  personalBest: number | null;\n  done: boolean;\n  log: { setsDone: number; valueDone: number } | null;\n}\n\ninterface TodayCircuitItem {\n  kind: "circuit";\n  campCircuitId: string;\n  campId: string;\n  campName: string;\n  name: string;\n  description: string | null;\n  items: { exerciseId?: string; name: string }[];\n  workSeconds: number;\n  restSeconds: number;\n  rounds: number;\n  roundRestSeconds: number;\n  done: boolean;\n}\n\ninterface NewBadge {\n  key: string;\n  name: string;\n  description: string;\n  emoji: string;\n}\n\n// Repos par defaut entre chaque serie lors d\'un chrono rapide lance sur un seul exercice\nconst QUICK_CHRONO_REST_SECONDS = 15;\n\nfunction targetLabelFor(item: TodayExerciseItem): string {\n  const unitLabel = item.unit === "REPS" ? "reps" : "sec";\n  return item.targetMode === "MAX"\n    ? `${item.targetSets} serie${item.targetSets > 1 ? "s" : ""} à fond${\n        item.personalBest\n          ? ` (record : ${item.unit === "SECONDS" ? secondsToMMSS(item.personalBest) : item.personalBest} ${unitLabel})`\n          : ""\n      }`\n    : `${item.targetSets} x ${\n        item.unit === "SECONDS" && item.targetValue ? secondsToMMSS(item.targetValue) : item.targetValue\n      } ${item.unit === "SECONDS" ? "" : unitLabel}`;\n}\n\nexport default function Today() {\n  const { user } = useAuth();\n  const [items, setItems] = useState<TodayExerciseItem[] | null>(null);\n  const [circuits, setCircuits] = useState<TodayCircuitItem[]>([]);\n  const [editingId, setEditingId] = useState<string | null>(null); // campExerciseId (simple) ou exerciseId (groupe)\n  const [selectedCampIds, setSelectedCampIds] = useState<string[]>([]);\n  const [sets, setSets] = useState(0);\n  const [value, setValue] = useState(0);\n  const [celebrating, setCelebrating] = useState<NewBadge[]>([]);\n  const [isRestToday, setIsRestToday] = useState(false);\n  const [restBusy, setRestBusy] = useState(false);\n  const [viewingMedia, setViewingMedia] = useState<TodayExerciseItem | null>(null);\n  const [runner, setRunner] = useState<\n    | { type: "exercise"; item: TodayExerciseItem }\n    | { type: "circuit"; item: TodayCircuitItem }\n    | null\n  >(null);\n\n  function load() {\n    api\n      .get<{ date: string; items: TodayExerciseItem[]; circuits: TodayCircuitItem[] }>("/today")\n      .then((res) => {\n        setItems(res.items);\n        setCircuits(res.circuits);\n      });\n  }\n  useEffect(load, []);\n\n  useEffect(() => {\n    const todayKey = new Date().toISOString().slice(0, 10);\n    api.get<{ date: string }[]>("/rest-days").then((days) => {\n      setIsRestToday(days.some((d) => d.date.slice(0, 10) === todayKey));\n    });\n  }, []);\n\n  async function toggleRestDay() {\n    setRestBusy(true);\n    try {\n      if (isRestToday) {\n        await api.del("/rest-days");\n        setIsRestToday(false);\n      } else {\n        await api.post("/rest-days", {});\n        setIsRestToday(true);\n      }\n    } finally {\n      setRestBusy(false);\n    }\n  }\n\n  // Regroupe les exercices identiques (meme exerciseId) presents dans plusieurs camps,\n  // pour proposer une validation combinee plutot que deux cartes separees.\n  const groups = useMemo(() => {\n    const map = new Map<string, TodayExerciseItem[]>();\n    items?.forEach((item) => {\n      const arr = map.get(item.exerciseId) ?? [];\n      arr.push(item);\n      map.set(item.exerciseId, arr);\n    });\n    return [...map.values()];\n  }, [items]);\n\n  function startEditingSingle(item: TodayExerciseItem) {\n    setEditingId(item.campExerciseId);\n    setSelectedCampIds([item.campId]);\n    setSets(item.log?.setsDone ?? item.targetSets);\n    setValue(item.log?.valueDone ?? item.targetValue ?? item.personalBest ?? 0);\n  }\n\n  function startEditingGroup(group: TodayExerciseItem[]) {\n    const notDone = group.filter((i) => !i.done);\n    setEditingId(group[0].exerciseId);\n    setSelectedCampIds(notDone.map((i) => i.campId));\n    const ref = notDone[0] ?? group[0];\n    setSets(ref.targetSets);\n    setValue(ref.targetValue ?? ref.personalBest ?? 0);\n  }\n\n  async function confirmCampIds(exerciseId: string, campIds: string[]) {\n    if (campIds.length === 0) {\n      setEditingId(null);\n      return;\n    }\n    const res = await api.post<{ newBadges: NewBadge[] }>("/logs", {\n      campIds,\n      exerciseId,\n      setsDone: sets,\n      valueDone: value,\n    });\n    setEditingId(null);\n    load();\n    if (res.newBadges?.length) setCelebrating(res.newBadges);\n  }\n\n  async function undo(item: TodayExerciseItem) {\n    await api.del(`/logs?campId=${item.campId}&exerciseId=${item.exerciseId}`);\n    load();\n  }\n\n  async function onExerciseChronoComplete(item: TodayExerciseItem) {\n    const res = await api.post<{ newBadges: NewBadge[] }>("/logs", {\n      campId: item.campId,\n      exerciseId: item.exerciseId,\n      setsDone: item.targetSets,\n      valueDone: item.targetValue ?? 0,\n    });\n    setRunner(null);\n    load();\n    if (res.newBadges?.length) setCelebrating(res.newBadges);\n  }\n\n  async function onCircuitComplete(item: TodayCircuitItem, totalDurationSeconds: number) {\n    const res = await api.post<{ newBadges: NewBadge[] }>(`/camp-circuits/${item.campCircuitId}/log`, {\n      durationSeconds: totalDurationSeconds,\n    });\n    setRunner(null);\n    load();\n    if (res.newBadges?.length) setCelebrating(res.newBadges);\n  }\n\n  if (runner?.type === "exercise") {\n    const item = runner.item;\n    return (\n      <div className="max-w-md mx-auto">\n        <CircuitRunner\n          items={[{ name: item.exerciseName }]}\n          workSeconds={item.targetValue ?? 30}\n          restSeconds={0}\n          rounds={item.targetSets}\n          roundRestSeconds={QUICK_CHRONO_REST_SECONDS}\n          onComplete={() => onExerciseChronoComplete(item)}\n          onCancel={() => setRunner(null)}\n        />\n      </div>\n    );\n  }\n\n  if (runner?.type === "circuit") {\n    const item = runner.item;\n    return (\n      <div className="max-w-md mx-auto">\n        <CircuitRunner\n          items={item.items.map((i) => ({ name: i.name }))}\n          workSeconds={item.workSeconds}\n          restSeconds={item.restSeconds}\n          rounds={item.rounds}\n          roundRestSeconds={item.roundRestSeconds}\n          onComplete={(duration) => onCircuitComplete(item, duration)}\n          onCancel={() => setRunner(null)}\n        />\n      </div>\n    );\n  }\n\n  const doneCount = (items?.filter((i) => i.done).length ?? 0) + circuits.filter((c) => c.done).length;\n  const total = (items?.length ?? 0) + circuits.length;\n\n  return (\n    <div className="max-w-xl">\n      {viewingMedia && (\n        <ExerciseMediaModal\n          name={viewingMedia.exerciseName}\n          imageBase64={viewingMedia.imageBase64}\n          videoUrl={viewingMedia.videoUrl}\n          onClose={() => setViewingMedia(null)}\n        />\n      )}\n\n      {celebrating.length > 0 && (\n        <div className="bg-accent/10 border border-accent rounded-xl p-4 mb-5">\n          {celebrating.map((b) => (\n            <p key={b.key} className="text-sm">\n              <span className="text-xl mr-2">{b.emoji}</span>\n              Nouveau badge : <span className="font-semibold">{b.name}</span> — {b.description}\n            </p>\n          ))}\n          <button onClick={() => setCelebrating([])} className="text-xs text-muted hover:text-text mt-2">\n            Fermer\n          </button>\n        </div>\n      )}\n\n      <h1 className="font-display text-3xl uppercase tracking-wide mb-1">Salut {user?.name?.split(" ")[0] ?? ""} 👋</h1>\n      <p className="text-muted text-sm mb-3">\n        {total === 0\n          ? "Rien de prevu aujourd\'hui."\n          : `${doneCount} / ${total} séance${total > 1 ? "s" : ""} validee${doneCount > 1 ? "s" : ""}.`}\n      </p>\n\n      {isRestToday ? (\n        <div className="bg-success/10 border border-success rounded-xl p-3 mb-5 flex items-center justify-between gap-3">\n          <p className="text-sm">😴 Jour de repos justifie — ta serie de régularité n\'est pas cassee aujourd\'hui.</p>\n          <button\n            onClick={toggleRestDay}\n            disabled={restBusy}\n            className="text-xs text-muted hover:text-accent shrink-0"\n          >\n            Annuler\n          </button>\n        </div>\n      ) : (\n        <button\n          onClick={toggleRestDay}\n          disabled={restBusy}\n          className="text-xs text-muted hover:text-accent mb-5 underline decoration-dotted"\n        >\n          😴 Marquer aujourd\'hui comme jour de repos (blessure, voyage...)\n        </button>\n      )}\n\n      {items === null && <p className="text-muted">Chargement...</p>}\n\n      {items?.length === 0 && circuits.length === 0 && (\n        <div className="bg-surface border border-dashed border-border rounded-xl p-8 text-center">\n          <p className="text-muted text-sm mb-3">\n            Rien de prevu aujourd\'hui — profite de ta journee, ou va voir tes camps pour en rejoindre ou en créer un\n            si l\'envie de bouger te prend !\n          </p>\n          <Link to="/camps" className="text-accent hover:text-accentSoft text-sm">\n            Voir mes camps\n          </Link>\n        </div>\n      )}\n\n      {circuits.length > 0 && (\n        <div className="space-y-3 mb-4">\n          {circuits.map((c) => (\n            <div\n              key={c.campCircuitId}\n              className={`bg-surface border rounded-xl p-4 ${c.done ? "border-success/50" : "border-border"}`}\n            >\n              <div className="flex items-center justify-between gap-3 flex-wrap">\n                <div>\n                  <p className="font-medium">🔁 {c.name}</p>\n                  <p className="text-xs text-muted">\n                    {c.campName} · {c.rounds} tour{c.rounds > 1 ? "s" : ""} · {c.items.length} exercice\n                    {c.items.length > 1 ? "s" : ""}\n                  </p>\n                  {c.description && <p className="text-xs text-muted italic mt-0.5">"{c.description}"</p>}\n                </div>\n                {c.done ? (\n                  <span className="text-success text-sm shrink-0">✓ Fait</span>\n                ) : (\n                  <button\n                    onClick={() => setRunner({ type: "circuit", item: c })}\n                    className="bg-accent hover:bg-accentSoft transition-colors text-bg font-semibold rounded-md px-4 py-2 text-sm shrink-0"\n                  >\n                    ⏱ Lancer\n                  </button>\n                )}\n              </div>\n            </div>\n          ))}\n        </div>\n      )}\n\n      <div className="space-y-3">\n        {groups.map((group) => {\n          const first = group[0];\n          const isGrouped = group.length > 1;\n          const unitLabel = first.unit === "REPS" ? "reps" : "sec";\n          const hasMedia = !!(first.imageBase64 || first.videoUrl);\n          const allDone = group.every((i) => i.done);\n          const isEditing = editingId === (isGrouped ? first.exerciseId : first.campExerciseId);\n          const canQuickChrono = !isGrouped && first.unit === "SECONDS" && first.targetMode === "FIXED" && !first.done;\n\n          return (\n            <div\n              key={first.exerciseId}\n              className={`bg-surface border rounded-xl p-4 transition-colors ${\n                allDone ? "border-success/50" : "border-border"\n              }`}\n            >\n              <div className="flex items-center justify-between gap-3 flex-wrap">\n                <div>\n                  <button\n                    onClick={() => hasMedia && setViewingMedia(first)}\n                    className={`font-medium text-left ${hasMedia ? "underline decoration-dotted hover:text-accent" : ""}`}\n                    title={hasMedia ? "Voir la photo/video de l\'exercice" : undefined}\n                  >\n                    {first.exerciseName} {hasMedia && "📷"}\n                  </button>\n                  {!isGrouped ? (\n                    <p className="text-xs text-muted">\n                      {first.campName} · objectif {targetLabelFor(first)}\n                    </p>\n                  ) : (\n                    <div className="text-xs text-muted space-y-0.5">\n                      {group.map((i) => (\n                        <p key={i.campId}>\n                          {i.done ? "✓ " : ""}\n                          {i.campName} · {targetLabelFor(i)}\n                        </p>\n                      ))}\n                    </div>\n                  )}\n                  {first.description && <p className="text-xs text-muted italic mt-0.5">"{first.description}"</p>}\n                </div>\n\n                {!isEditing && (\n                  <div className="flex items-center gap-2 shrink-0">\n                    {canQuickChrono && (\n                      <button\n                        onClick={() => setRunner({ type: "exercise", item: first })}\n                        title="Lancer le chrono pour cet exercice"\n                        className="w-10 h-10 rounded-full flex items-center justify-center border-2 border-accent text-accent hover:bg-accent/10"\n                      >\n                        ⏱\n                      </button>\n                    )}\n                    {allDone ? (\n                      <button\n                        onClick={() => undo(first)}\n                        className="stamp-btn pop-success w-12 h-12 rounded-full flex items-center justify-center text-lg font-bold border-2 bg-success/20 border-success text-success"\n                        title="Fait - clique pour annuler"\n                      >\n                        ✓\n                      </button>\n                    ) : (\n                      <button\n                        onClick={() => (isGrouped ? startEditingGroup(group) : startEditingSingle(first))}\n                        className="stamp-btn w-12 h-12 rounded-full flex items-center justify-center text-lg font-bold border-2 bg-surface2 border-border text-muted hover:border-accent hover:text-accent"\n                        title="Marquer comme fait"\n                      />\n                    )}\n                  </div>\n                )}\n              </div>\n\n              {!isGrouped && first.done && first.log && (\n                <p className="text-xs text-muted mt-2">\n                  Réalisé : {first.log.setsDone} x{" "}\n                  {first.unit === "SECONDS" ? secondsToMMSS(first.log.valueDone) : `${first.log.valueDone} ${unitLabel}`}\n                </p>\n              )}\n\n              {isEditing && (\n                <div className="mt-3 bg-surface2 border border-border rounded-md p-3 space-y-3">\n                  {isGrouped && (\n                    <div>\n                      <p className="text-xs text-muted mb-1">Valider pour :</p>\n                      <div className="flex flex-wrap gap-2">\n                        {group\n                          .filter((i) => !i.done)\n                          .map((i) => (\n                            <label key={i.campId} className="flex items-center gap-1.5 text-sm">\n                              <input\n                                type="checkbox"\n                                checked={selectedCampIds.includes(i.campId)}\n                                onChange={(e) =>\n                                  setSelectedCampIds((prev) =>\n                                    e.target.checked ? [...prev, i.campId] : prev.filter((c) => c !== i.campId)\n                                  )\n                                }\n                              />\n                              {i.campName}\n                            </label>\n                          ))}\n                      </div>\n                    </div>\n                  )}\n                  <div className="flex items-end gap-3 flex-wrap">\n                    <div>\n                      <label className="block text-xs text-muted mb-1">Series faites</label>\n                      <input\n                        type="number"\n                        min={0}\n                        value={sets}\n                        onChange={(e) => setSets(Number(e.target.value))}\n                        className="w-20 bg-surface border border-border rounded-md px-2 py-1"\n                      />\n                    </div>\n                    <div>\n                      <label className="block text-xs text-muted mb-1">{unitLabel} par serie</label>\n                      {first.unit === "SECONDS" ? (\n                        <DurationInput totalSeconds={value} onChange={setValue} />\n                      ) : (\n                        <input\n                          type="number"\n                          min={0}\n                          value={value}\n                          onChange={(e) => setValue(Number(e.target.value))}\n                          className="w-20 bg-surface border border-border rounded-md px-2 py-1"\n                        />\n                      )}\n                    </div>\n                    <button\n                      onClick={() => confirmCampIds(first.exerciseId, selectedCampIds)}\n                      className="bg-accent text-bg font-semibold rounded-md px-4 py-1.5 text-sm"\n                    >\n                      Valider\n                    </button>\n                    <button onClick={() => setEditingId(null)} className="text-muted text-sm px-2">\n                      Annuler\n                    </button>\n                  </div>\n                </div>\n              )}\n            </div>\n          );\n        })}\n      </div>\n    </div>\n  );\n}\n'
FILES['frontend/src/pages/Dashboard.tsx'] = 'import { useEffect, useState } from "react";\nimport { Link } from "react-router-dom";\nimport { api } from "../api/client";\n\ninterface CampSummary {\n  id: string;\n  name: string;\n  code: string;\n  exercises: { exercise: { id: string; name: string } }[];\n  _count: { members: number };\n}\n\nexport default function Dashboard() {\n  const [camps, setCamps] = useState<CampSummary[] | null>(null);\n\n  useEffect(() => {\n    api.get<CampSummary[]>("/camps/mine").then(setCamps);\n  }, []);\n\n  return (\n    <div>\n      <div className="flex items-center justify-between mb-6 flex-wrap gap-3">\n        <div>\n          <h1 className="font-display text-3xl uppercase tracking-wide mb-1">Mes camps</h1>\n          <p className="text-muted text-sm">Les groupes d\'entraînement auxquels tu participes.</p>\n        </div>\n        <div className="flex gap-2">\n          <Link\n            to="/camps/rejoindre"\n            className="bg-surface2 hover:bg-border transition-colors border border-border rounded-md px-4 py-2 text-sm"\n          >\n            Intégrer un camp\n          </Link>\n          <Link\n            to="/camps/creer"\n            className="brand-gradient hover:opacity-90 transition-opacity text-white font-semibold rounded-md px-4 py-2 text-sm"\n          >\n            + Nouveau camp\n          </Link>\n        </div>\n      </div>\n\n      {camps === null && <p className="text-muted">Chargement...</p>}\n\n      {camps?.length === 0 && (\n        <div className="bg-surface border border-dashed border-border rounded-xl p-8 text-center">\n          <p className="font-display text-xl uppercase tracking-wide mb-2">C\'est calme par ici 🌱</p>\n          <p className="text-muted text-sm mb-5">\n            Cree ton premier camp — pas besoin d\'etre sportif, juste l\'envie de bouger un peu plus — ou rejoins\n            celui d\'un proche avec son code.\n          </p>\n        </div>\n      )}\n\n      <div className="grid gap-4 sm:grid-cols-2">\n        {camps?.map((camp) => (\n          <Link\n            key={camp.id}\n            to={`/camps/${camp.id}`}\n            className="bg-surface border border-border rounded-xl p-5 hover:border-accent/50 transition-colors"\n          >\n            <div className="flex items-center justify-between mb-2">\n              <h2 className="font-display text-lg uppercase tracking-wide">{camp.name}</h2>\n              <span className="font-mono text-xs bg-surface2 border border-border rounded px-2 py-1 text-muted">\n                {camp.code}\n              </span>\n            </div>\n            <p className="text-sm text-muted mb-1">\n              {camp.exercises.length} exercice{camp.exercises.length > 1 ? "s" : ""} · {camp._count.members} membre\n              {camp._count.members > 1 ? "s" : ""}\n            </p>\n            <p className="text-xs text-muted truncate">\n              {camp.exercises.map((e) => e.exercise.name).join(" · ")}\n            </p>\n          </Link>\n        ))}\n      </div>\n    </div>\n  );\n}\n'

